  [14516] = { "敵を打ち、通常より大きな近接ダメージを与えます。", nil, 0xcffda50e, nil, "um" },
  [14517] = { "敵に$N1のダメージを与え、Crusader Strikeごとにその敵が受けるHolyダメージを$N2増加させます。最大5回まで重ねられます。効果時間は$D1です。", "受けるHolyダメージが増加しています。", 0xe1adbda3, 0x6508d97f, "uu" },
  [14518] = { "敵に$N1のダメージを与え、Crusader Strikeごとにその敵が受けるHolyダメージを$N2増加させます。最大5回まで重ねられます。効果時間は$D1です。", "受けるHolyダメージが増加しています。", 0xe1adbda3, 0x6508d97f, "uu" },
  [14520] = { "Smite、Holy Fire、および即時詠唱呪文のマナコストを$N1%軽減します。", nil, 0x7026d4cd, nil, "um" },
  [14521] = { "詠唱中もマナ回復の$N1%が継続します。", nil, 0x86815c0c, nil, "um" },
  [14522] = { "自分が受けるStun、Fear、Silence効果の持続時間を$N1%短縮します。", nil, 0x3ff087ba, nil, "um" },
  [14523] = { "Holy呪文で発生する脅威を$N1%軽減し、自分が受けるStun、Fear、Silence効果の持続時間を$N2%短縮します。", nil, 0xd2bd79d4, nil, "um" },
  [14524] = { "Wandによるダメージを$N1%上げます。", nil, 0xf80826f8, nil, "um" },
  [14530] = { "$D1の間、走る速度を$N1%上げます。", "走る速度が$N1%上昇します。", 0x61fe647b, 0xdb6814b9, "uu" },
  [14531] = { "近接攻撃または遠隔攻撃でクリティカルを受けた後、$N1%の確率で$D1の間Focused Castingを得ます。Focused Castingの効果中はダメージを受けても詠唱時間が失われず、Interrupt効果への抵抗が$N3%上昇します。", nil, 0x2eccaa59, nil, "um" },
  [14532] = { "$D1の間、近くの敵が受けるPhysicalダメージを$N1%増加させます。", "受ける物理ダメージが$N1%増加しています。", 0x087a6362, 0xed6770df, "uu" },
  [14533] = { "$D1の間、近くの敵が受けるFire、Frost、Arcaneダメージを$N1%増加させます。", "受けるFire、Frost、Arcaneダメージが$N1%増加しています。", 0xe604a223, 0x294b47dc, "uu" },
  [14534] = { "$D1の間、近くの敵の攻撃間隔を$N1%延ばします。", "攻撃間隔が$N1%長くなっています。", 0xcfd53330, 0x4f44ab25, "uu" },
  [14535] = { "$D1の間、近くの敵のすべての能力値を$N1%低下させます。", "すべての能力値が$N1%低下しています。", 0xcf0e623a, 0xb4619e26, "uu" },
