  [14875] = { "敵に苦悶の呪いをかけ、$D2の間、$D1ごとにShadowダメージを与えます。ウォーロックごとに、1つの対象にかけられる呪いは1つだけです。", "$D1ごとにShadowダメージを受けています。", 0x7a8de5d9, 0x1bf49534, "uu" },
