  [14895] = { "即座に敵を圧倒し、武器ダメージに$N1を加えたダメージを与えます。対象が回避した後にのみ使用できます。Overpowerはブロック、回避、受け流しされません。", nil, 0xe292d06f, nil, "um" },
  [14897] = { "$D1の間、敵の攻撃間隔を$N1%延ばし、移動速度を$N2%低下させます。", "攻撃間隔が$N1%長くなっています。\n移動速度が$N2%低下しています。", 0x09499b94, 0xb6675ce0, "uu" },
  [14898] = { "呪文による回復量を$N1%増加させます。", nil, 0x7dad99a1, nil, "um" },
  [14900] = { "傷ついた味方に癒しのエネルギーを注ぎ込み、エネルギーは近くにいる別の味方へ広がります。この呪文は最大$N1体の対象に作用しますが、次の対象に移るたびに回復量が50%減少します。", nil, 0xaf264114, nil, "um" },
